import{_ as s,o as n,c as e,a5 as i}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"99. Packaging, Versioning, and Documentation","description":"The Little Book of C — 99. Packaging, Versioning, and Documentation","frontmatter":{"title":"99. Packaging, Versioning, and Documentation","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Building Real Projects"],"description":"The Little Book of C — 99. Packaging, Versioning, and Documentation","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":99,"sidebarWeight":99,"lang":"en-US","alternateEn":"/posts/c教程/en-US/10-Building Real Projects/099-Packaging, Versioning, and Documentation","alternateZh":"/posts/c教程/zh-CN/10-真实项目/099-Packaging, Versioning, and Documentation"},"headers":[],"relativePath":"posts/c教程/en-US/10-Building Real Projects/099-Packaging, Versioning, and Documentation.md","filePath":"posts/c教程/en-US/10-Building Real Projects/099-Packaging, Versioning, and Documentation.md","lastUpdated":1790163617000}'),p={name:"posts/c教程/en-US/10-Building Real Projects/099-Packaging, Versioning, and Documentation.md"};function l(t,a,o,c,d,r){return n(),e("div",null,[...a[0]||(a[0]=[i(`<p>[中文版本](/posts/c教程/zh-CN/10-真实项目/099-Packaging, Versioning, and Documentation)</p><p>You’ve written real C programs—now it’s time to package, version, and document them like a professional. This is what makes your code usable by others and maintainable by your future self.</p><h4 id="step-1-the-goal-of-packaging" tabindex="-1">Step 1. The goal of packaging <a class="header-anchor" href="#step-1-the-goal-of-packaging" aria-label="Permalink to &quot;Step 1. The goal of packaging&quot;">​</a></h4><p>Packaging is about making your project easy to:</p><ul><li>build (<code>make</code>,<code>cmake</code>, or<code>meson</code>)</li><li>install (<code>make install</code>)</li><li>link (<code>pkg-config</code>)</li><li>use (<code>#include &quot;yourlib.h&quot;</code>)</li></ul><p>You’ll create a structure that helps others build and use your code without guessing.</p><h4 id="step-2-standard-project-layout" tabindex="-1">Step 2. Standard project layout <a class="header-anchor" href="#step-2-standard-project-layout" aria-label="Permalink to &quot;Step 2. Standard project layout&quot;">​</a></h4><p>A simple, conventional layout for a C project:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>myproject/</span></span>
<span class="line"><span>├── include/</span></span>
<span class="line"><span>│   └── myproject.h</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>│   ├── main.c</span></span>
<span class="line"><span>│   └── util.c</span></span>
<span class="line"><span>├── tests/</span></span>
<span class="line"><span>│   └── test_basic.c</span></span>
<span class="line"><span>├── Makefile</span></span>
<span class="line"><span>├── README.md</span></span>
<span class="line"><span>└── LICENSE</span></span></code></pre></div><ul><li><code>include/</code> holds headers that others can include</li><li><code>src/</code> holds your implementation files</li><li><code>tests/</code> holds unit tests</li><li><code>Makefile</code> defines how to build and install</li></ul><h4 id="step-3-tiny-code-a-simple-reusable-library" tabindex="-1">Step 3. Tiny Code: a simple reusable library <a class="header-anchor" href="#step-3-tiny-code-a-simple-reusable-library" aria-label="Permalink to &quot;Step 3. Tiny Code: a simple reusable library&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// include/myproject.h</span></span>
<span class="line"><span>#ifndef MYPROJECT_H</span></span>
<span class="line"><span>#define MYPROJECT_H</span></span>
<span class="line"><span>int add(int a, int b);</span></span>
<span class="line"><span>int sub(int a, int b);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// src/myproject.c</span></span>
<span class="line"><span>#include &quot;myproject.h&quot;</span></span>
<span class="line"><span>int add(int a, int b) { return a + b; }</span></span>
<span class="line"><span>int sub(int a, int b) { return a - b; }</span></span></code></pre></div><h4 id="step-4-minimal-makefile" tabindex="-1">Step 4. Minimal Makefile <a class="header-anchor" href="#step-4-minimal-makefile" aria-label="Permalink to &quot;Step 4. Minimal Makefile&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC      = gcc</span></span>
<span class="line"><span>CFLAGS  = -std=c23 -O2 -Wall -Iinclude</span></span>
<span class="line"><span>LDFLAGS =</span></span>
<span class="line"><span>SRC = $(wildcard src/*.c)</span></span>
<span class="line"><span>OBJ = $(SRC:.c=.o)</span></span>
<span class="line"><span>LIB = libmyproject.a</span></span>
<span class="line"><span>.PHONY: all clean install uninstall</span></span>
<span class="line"><span>all: $(LIB)</span></span>
<span class="line"><span>$(LIB): $(OBJ)</span></span>
<span class="line"><span>    ar rcs $@ $^</span></span>
<span class="line"><span>%.o: %.c</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) -c $&lt; -o $@</span></span>
<span class="line"><span>install:</span></span>
<span class="line"><span>    mkdir -p /usr/local/include/myproject</span></span>
<span class="line"><span>    cp include/*.h /usr/local/include/myproject/</span></span>
<span class="line"><span>    cp $(LIB) /usr/local/lib/</span></span>
<span class="line"><span>uninstall:</span></span>
<span class="line"><span>    rm -f /usr/local/lib/$(LIB)</span></span>
<span class="line"><span>    rm -rf /usr/local/include/myproject</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f $(OBJ) $(LIB)</span></span></code></pre></div><p>Build the library:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span>
<span class="line"><span>sudo make install</span></span></code></pre></div><p>Then another project can link against it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c -lmyproject -L/usr/local/lib -I/usr/local/include/myproject</span></span></code></pre></div><h4 id="step-5-versioning-your-releases" tabindex="-1">Step 5. Versioning your releases <a class="header-anchor" href="#step-5-versioning-your-releases" aria-label="Permalink to &quot;Step 5. Versioning your releases&quot;">​</a></h4><p>Follow semantic versioning:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vMAJOR.MINOR.PATCH</span></span></code></pre></div><p>Examples:</p><ul><li><code>v1.0.0</code>– stable release</li><li><code>v1.1.0</code>– new feature, backward compatible</li><li><code>v1.1.1</code>– bug fix, no API change</li><li><code>v2.0.0</code>– breaking API change</li></ul><p>Tag your releases in git:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git tag -a v1.0.0 -m &quot;First stable release&quot;</span></span>
<span class="line"><span>git push origin v1.0.0</span></span></code></pre></div><h4 id="step-6-create-a-pkg-config-file" tabindex="-1">Step 6. Create a pkg-config file <a class="header-anchor" href="#step-6-create-a-pkg-config-file" aria-label="Permalink to &quot;Step 6. Create a pkg-config file&quot;">​</a></h4><p><code>pkg-config</code> lets others compile your library easily.</p><p>Create<code>myproject.pc</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>prefix=/usr/local</span></span>
<span class="line"><span>exec_prefix=\${prefix}</span></span>
<span class="line"><span>libdir=\${exec_prefix}/lib</span></span>
<span class="line"><span>includedir=\${prefix}/include/myproject</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Name: myproject</span></span>
<span class="line"><span>Description: Tiny math helper library</span></span>
<span class="line"><span>Version: 1.0.0</span></span>
<span class="line"><span>Libs: -L\${libdir} -lmyproject</span></span>
<span class="line"><span>Cflags: -I\${includedir}</span></span></code></pre></div><p>Install it in<code>/usr/local/lib/pkgconfig/</code> and test:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pkg-config --cflags --libs myproject</span></span></code></pre></div><h4 id="step-7-documentation-with-markdown-and-doxygen" tabindex="-1">Step 7. Documentation with Markdown and Doxygen <a class="header-anchor" href="#step-7-documentation-with-markdown-and-doxygen" aria-label="Permalink to &quot;Step 7. Documentation with Markdown and Doxygen&quot;">​</a></h4><p>Keep a clear README.md at the root:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># myproject</span></span>
<span class="line"><span>A tiny example C library for arithmetic functions.</span></span>
<span class="line"><span>## Build</span></span></code></pre></div><p>make sudo make install</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>## Usage</span></span>
<span class="line"><span>\`\`\`c</span></span>
<span class="line"><span>#include &lt;myproject.h&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int main() {</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, add(3, 4));</span></span>
<span class="line"><span>}</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>For API documentation, use **Doxygen**:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>\`\`\`bash</span></span>
<span class="line"><span>sudo apt install doxygen</span></span>
<span class="line"><span>doxygen -g</span></span></code></pre></div><p>Edit<code>Doxyfile</code> to include your source paths, then run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>doxygen Doxyfile</span></span></code></pre></div><p>Docs will appear in<code>html/</code> or<code>latex/</code>.</p><h4 id="step-8-licensing" tabindex="-1">Step 8. Licensing <a class="header-anchor" href="#step-8-licensing" aria-label="Permalink to &quot;Step 8. Licensing&quot;">​</a></h4><p>Add a<code>LICENSE</code> file so others know how they can use your code. Common ones:</p><ul><li>MIT License: simple, permissive</li><li>Apache 2.0: adds patent protection</li><li>GPLv3: ensures derivatives remain open</li></ul><p>Example MIT License header for your source files:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/* </span></span>
<span class="line"><span> * Copyright (c) 2025 Your Name</span></span>
<span class="line"><span> * Licensed under the MIT License.</span></span>
<span class="line"><span> */</span></span></code></pre></div><h4 id="step-9-continuous-integration-optional" tabindex="-1">Step 9. Continuous Integration (optional) <a class="header-anchor" href="#step-9-continuous-integration-optional" aria-label="Permalink to &quot;Step 9. Continuous Integration (optional)&quot;">​</a></h4><p>Add GitHub Actions or another CI service:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># .github/workflows/build.yml</span></span>
<span class="line"><span>name: Build and Test</span></span>
<span class="line"><span>on: [push, pull_request]</span></span>
<span class="line"><span>jobs:</span></span>
<span class="line"><span>  build:</span></span>
<span class="line"><span>    runs-on: ubuntu-latest</span></span>
<span class="line"><span>    steps:</span></span>
<span class="line"><span>    - uses: actions/checkout@v3</span></span>
<span class="line"><span>    - run: make</span></span>
<span class="line"><span>    - run: make test || echo &quot;No tests yet&quot;</span></span></code></pre></div><p>Now every push builds automatically.</p><h4 id="step-10-why-this-matters" tabindex="-1">Step 10. Why this matters <a class="header-anchor" href="#step-10-why-this-matters" aria-label="Permalink to &quot;Step 10. Why this matters&quot;">​</a></h4><p>Professional packaging is part of being a systems engineer:</p><ul><li>Your projects build reproducibly.</li><li>Others can install, link, and use them easily.</li><li>Documentation and version tags create confidence.</li><li>Licensing clarifies ownership.</li></ul><p>You have now moved from C programmer to C maintainer, the person others trust to deliver solid, reusable, and well-documented software.</p><p>Next is 100. Practice: Build Your Own Mini Project, where you will bring everything together, writing, building, debugging, and packaging a complete small system in pure C.</p>`,55)])])}const g=s(p,[["render",l]]);export{h as __pageData,g as default};
